<?php
declare(strict_types=1);
namespace App\Modules\Pharmacies\Controllers;
use App\Http\Controllers\Controller;
use App\Modules\Tenancy\Services\OfficineAccess;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
use Carbon\CarbonImmutable;
final class PharmacyGuardController extends Controller {
 private function office(Request $r,bool $write=false):int{$office=(int)app('tenant.officine_id');$permissions=$r->attributes->get('officine.permissions',[]);$admin=$r->attributes->get('officine.is_admin')===true;abort_unless($admin||in_array($write?'gardes.write':'gardes.read',$permissions,true),403,'Autorisation insuffisante.');return $office;}
 public function index(Request $r){$office=$this->office($r);$q=DB::table('pharmacy_guards')->where('officine_id',$office);if($r->filled('from'))$q->where('ends_at','>=',$r->query('from'));if($r->filled('to'))$q->where('starts_at','<=',$r->query('to'));if($r->filled('search'))$q->where('pharmacy_name','like','%'.$r->query('search').'%');$permissions=(array)$r->attributes->get('officine.permissions',[]);return response()->json(['data'=>$q->orderBy('starts_at')->get(),'can_write'=>$r->attributes->get('officine.is_admin')===true||in_array('gardes.write',$permissions,true)]);}
 public function store(Request $r){$office=$this->office($r,true);$d=$this->validateData($r);$id=DB::transaction(function()use($r,$office,$d){DB::table('officines')->where('id',$office)->lockForUpdate()->firstOrFail();$this->assertNoOverlap($office,$d);return DB::table('pharmacy_guards')->insertGetId($this->values($d,$office,$r)+['created_at'=>now(),'updated_at'=>now()]);});OfficineAccess::audit($r,$office,'gardes.created',['id'=>$id]);return response()->json(['data'=>DB::table('pharmacy_guards')->find($id)],201);}
 public function update(Request $r,int $id){$office=$this->office($r,true);$d=$this->validateData($r);DB::transaction(function()use($r,$office,$d,$id){DB::table('officines')->where('id',$office)->lockForUpdate()->firstOrFail();$q=DB::table('pharmacy_guards')->where('officine_id',$office)->where('id',$id);abort_unless($q->exists(),404);$this->assertNoOverlap($office,$d,$id);$q->update($this->values($d,$office,$r)+['updated_at'=>now()]);});OfficineAccess::audit($r,$office,'gardes.updated',['id'=>$id]);return response()->json(['data'=>DB::table('pharmacy_guards')->find($id)]);}
 public function destroy(Request $r,int $id){$office=$this->office($r,true);$deleted=DB::table('pharmacy_guards')->where('officine_id',$office)->where('id',$id)->delete();abort_unless($deleted,404);OfficineAccess::audit($r,$office,'gardes.deleted',['id'=>$id]);return response()->json(['deleted'=>true]);}
 private function validateData(Request $r):array{$d=$r->validate(['pharmacy_name'=>['required','string','max:180'],'phone'=>['nullable','string','max:40'],'address'=>['nullable','string','max:255'],'starts_at'=>['required','date'],'ends_at'=>['required','date','after:starts_at'],'reason'=>['nullable','string','max:500']]);if(CarbonImmutable::parse($d['ends_at'])->lessThanOrEqualTo(CarbonImmutable::parse($d['starts_at'])))throw ValidationException::withMessages(['ends_at'=>'La fin doit être postérieure au début.']);return $d;}
 private function assertNoOverlap(int $office,array $d,?int $except=null):void{$q=DB::table('pharmacy_guards')->where('officine_id',$office)->where('starts_at','<',$d['ends_at'])->where('ends_at','>',$d['starts_at']);if($except)$q->where('id','<>',$except);if($q->exists())throw ValidationException::withMessages(['starts_at'=>'Cette période chevauche une garde déjà déclarée.']);}
 private function values(array $d,int $office,Request $r):array{return ['officine_id'=>$office,'pharmacy_name'=>trim($d['pharmacy_name']),'phone'=>$d['phone']??null,'address'=>$d['address']??null,'starts_at'=>CarbonImmutable::parse($d['starts_at'])->utc(),'ends_at'=>CarbonImmutable::parse($d['ends_at'])->utc(),'reason'=>$d['reason']??null,'recorded_by'=>$r->user()->id];}
}
